                        'examples' => "// Função pura — sem efeitos colaterais\nconst calcularDesconto = (preco, percentual) => preco * (1 - percentual / 100);\n\nconsole.log(calcularDesconto(100, 20)); // 80\nconsole.log(calcularDesconto(250, 15)); // 212.5\n\n// Função com múltiplos retornos\nfunction validarIdade(idade) {\n  if (typeof idade !== 'number') return { valido: false, erro: 'Deve ser número' };\n  if (idade < 0 || idade > 150) return { valido: false, erro: 'Fora do intervalo' };\n  return { valido: true, categoria: idade >= 18 ? 'adulto' : 'menor' };\n}\n\nconsole.log(validarIdade(25)); // { valido: true, categoria: 'adulto' }",
