                        'tips' => 'Métodos que mutam o array original (push, pop, splice) podem causar bugs difíceis de rastrear em código funcional. Prefira operações imutáveis com spread: [...arr, novoItem] para adicionar, arr.filter(x => x !== item) para remover. React exige esse padrão.',
                        'examples' => "const carrinho = ['Notebook', 'Mouse'];\n\n// Adicionar item\ncarrinho.push('Teclado');\nconsole.log(carrinho.length); // 3\n\n// Verificar se item existe\nconsole.log(carrinho.includes('Mouse')); // true\n\n// Remover item por índice\ncarrinho.splice(1, 1); // Remove 'Mouse'\nconsole.log(carrinho); // ['Notebook', 'Teclado']\n\n// Versão IMUTÁVEL (preferida no React)\nconst novoCarrinho = carrinho.filter(item => item !== 'Mouse');\nconsole.log(novoCarrinho); // ['Notebook']",
