                        'tips' => 'Object.keys(obj) retorna as chaves, Object.values(obj) os valores, Object.entries(obj) pares [chave, valor]. Para clonar sem referência: const clone = { ...original }. Para merge: const merged = { ...obj1, ...obj2 }. São operações fundamentais em qualquer API.',
                        'examples' => "// Modelando um produto de e-commerce\nconst produto = {\n  id: 'SKU-001',\n  nome: 'AirPods Pro',\n  preco: 1999.90,\n  estoque: 15,\n  calcularTotal(quantidade) {\n    return (this.preco * quantidade).toFixed(2);\n  },\n  temEstoque() {\n    return this.estoque > 0;\n  }\n};\n\nconsole.log(produto.calcularTotal(2)); // '3999.80'\nconsole.log(produto.temEstoque());     // true\n\n// Listando todas as propriedades\nconsole.log(Object.keys(produto)); // ['id', 'nome', 'preco', ...]",
