                        'solution_code' => "const lista = document.querySelector('#lista'); const li = document.createElement('li'); li.textContent = 'Novo Item'; lista.appendChild(li);",
                        'tips' => 'Sempre use textContent ao invés de innerHTML com dados do usuário — previne XSS.',
                        'examples' => "const div = document.createElement('div');\ndiv.className = 'card';\ndocument.body.appendChild(div);",
                        'real_world_case' => 'Feeds de redes sociais criam cards de post dinamicamente via createElement.',
                        'docs_link' => 'https://developer.mozilla.org/pt-BR/docs/Web/API/Document/createElement',
