                        'title' => 'Module Pattern & IIFE',
                        'slug' => 'module-pattern',
                        'content' => "# Module Pattern e IIFE: Encapsulamento\n\nAntes dos módulos ES6, o Module Pattern era a forma de criar escopo privado em JavaScript.\n\n## IIFE — Immediately Invoked Function Expression:\n```js\n// Função que executa imediatamente e cria escopo isolado\n(function() {\n  const privado = 'só existe aqui';\n  console.log('executou!');\n})();\n// privado não existe fora\n```\n\n## Module Pattern completo:\n```js\nconst Carrinho = (function() {\n  // Privado — não acessível de fora\n  let _itens = [];\n  let _desconto = 0;\n\n  // Público — o que é exposto\n  return {\n    adicionar(item) { _itens.push(item); },\n    remover(id) { _itens = _itens.filter(i => i.id !== id); },\n    total() {\n      const soma = _itens.reduce((acc, i) => acc + i.preco, 0);\n      return soma * (1 - _desconto);\n    },\n    setDesconto(pct) { _desconto = pct / 100; }\n  };\n})();\n\nCarrinho.adicionar({ id: 1, preco: 100 });\nconsole.log(Carrinho.total()); // 100\n// Carrinho._itens — undefined (privado!)\n```\n\n## Por que ainda aprender?\n- Código legado usa esse padrão\n- Entender closures — conceito fundamental\n- jQuery, lodash e muitas libs são IIFEs",
                        'task' => 'Crie um módulo "Contador" usando IIFE que expõe métodos incrementar(), decrementar() e valor().',
                        'starter_code' => "const Contador = (function() {\n  let _count = 0;\n  return {\n    // Adicione os métodos\n  };\n})();\n\nContador.incrementar();\nconsole.log(Contador.valor());",
                        'solution_code' => "const Contador = (function() { let _count = 0; return { incrementar() { _count++; }, decrementar() { _count--; }, valor() { return _count; } }; })(); Contador.incrementar(); console.log(Contador.valor());",
                        'tips' => 'A variável _count é privada — só acessível pelos métodos expostos. É closures em ação.',
                        'examples' => "const API = (function() { const baseURL = 'https://api.exemplo.com'; return { get: async (path) => fetch(baseURL + path) }; })();",
                        'real_world_case' => 'jQuery ($ global) e muitas bibliotecas usam IIFE para não vazar variáveis internas.',
                        'docs_link' => 'https://developer.mozilla.org/pt-BR/docs/Glossary/IIFE',
