                        'title' => 'Factory Pattern: Fábricas de Objetos',
                        'slug' => 'factory-pattern',
                        'content' => "# Factory Pattern: Fábricas de Objetos\n\nFactory Functions criam objetos sem usar `new`, com mais flexibilidade e encapsulamento.\n\n## O problema com construtores:\n```js\n// Com new — problemas: 'this', herança, sem privacidade\nfunction User(nome, role) {\n  this.nome = nome;\n  this.role = role;\n}\nconst admin = new User('Ana', 'admin'); // e se esquecer o new?\n```\n\n## Factory Function — mais segura:\n```js\nfunction criarUser(nome, role) {\n  // Estado privado via closure\n  let _tentativasLogin = 0;\n\n  return {\n    nome,\n    role,\n    apresentar() { return \`\${nome} [\${role}]\`; },\n    tentarLogin() {\n      _tentativasLogin++;\n      if (_tentativasLogin > 3) throw new Error('Conta bloqueada');\n    },\n    getTentativas() { return _tentativasLogin; }\n  };\n}\n\nconst admin = criarUser('Ana', 'admin');\nadmin.apresentar();     // 'Ana [admin]'\nadmin._tentativasLogin; // undefined (privado!)\n```\n\n## Factory com configuração:\n```js\nfunction criarAPI(baseURL, timeout = 5000) {\n  return {\n    async get(path) { return fetch(baseURL + path, { signal: AbortSignal.timeout(timeout) }); },\n    async post(path, body) { return fetch(baseURL + path, { method: 'POST', body: JSON.stringify(body) }); }\n  };\n}\n\nconst api = criarAPI('https://api.exemplo.com', 3000);\n```",
