                        'title' => 'Singleton: Instância Única',
                        'slug' => 'singleton-pattern',
                        'content' => "# Singleton: Garantindo Uma Única Instância\n\nO Singleton garante que uma classe tenha **apenas uma instância** em toda a aplicação.\n\n## Casos de uso reais:\n- Pool de conexões com banco de dados\n- Cache global da aplicação\n- Logger centralizado\n- Configurações da aplicação\n\n## Implementação com classe:\n```js\nclass Config {\n  constructor() {\n    // Se já existe uma instância, retorna ela\n    if (Config._instance) return Config._instance;\n\n    this.tema = 'dark';\n    this.idioma = 'pt-BR';\n    this.debug = false;\n\n    Config._instance = this;\n  }\n\n  set(chave, valor) { this[chave] = valor; }\n  get(chave) { return this[chave]; }\n}\n\nconst cfg1 = new Config();\nconst cfg2 = new Config();\nconsole.log(cfg1 === cfg2); // true — mesma instância\n```\n\n## Implementação com closure (mais idiomático):\n```js\nconst Logger = (() => {\n  let _instance;\n  return {\n    getInstance() {\n      if (!_instance) _instance = { logs: [], log(msg) { this.logs.push(msg); console.log(msg); } };\n      return _instance;\n    }\n  };\n})();\n\nLogger.getInstance().log('App iniciou');\n```\n\n## Módulos ES6 são Singletons por natureza:\n```js\n// config.js — este objeto é o mesmo em toda a aplicação\nexport const config = { tema: 'dark' };\n```",
                        'task' => 'Implemente um Singleton para uma classe Config que só pode ter uma instância.',
                        'starter_code' => "class Config {\n  constructor() {\n    // Implemente o padrão Singleton\n  }\n}\nconst c1 = new Config();\nconst c2 = new Config();\nconsole.log(c1 === c2); // deve ser true",
                        'solution_code' => "class Config { constructor() { if(Config._instance) return Config._instance; Config._instance = this; this.env = 'production'; } } const c1 = new Config(); const c2 = new Config(); console.log(c1 === c2);",
