                    [
                        'title' => 'Generics: Código Reutilizável Tipado',
                        'slug' => 'ts-generics',
                        'content' => "# Generics: Código Reutilizável com Tipos\n\nGenerics permitem escrever funções e classes que funcionam com **qualquer tipo**, mantendo segurança.\n\n## O problema sem Generics:\n```ts\n// Função que aceita qualquer tipo mas perde informação\nfunction primeiro(arr: any[]): any { return arr[0]; }\nconst n = primeiro([1, 2, 3]); // TypeScript não sabe que é number\n```\n\n## Com Generics:\n```ts\nfunction primeiro<T>(arr: T[]): T { return arr[0]; }\n\nconst n = primeiro([1, 2, 3]);     // TypeScript infere: number\nconst s = primeiro(['a', 'b']);    // TypeScript infere: string\nconst u = primeiro<User>([user1]); // tipo explícito\n```\n\n## Generics com restrições:\n```ts\n// T deve ter a propriedade 'id'\nfunction buscarPorId<T extends { id: number }>(lista: T[], id: number): T | undefined {\n  return lista.find(item => item.id === id);\n}\n```\n\n## Múltiplos tipos genéricos:\n```ts\nfunction mapear<TInput, TOutput>(arr: TInput[], fn: (item: TInput) => TOutput): TOutput[] {\n  return arr.map(fn);\n}\n\nconst nomes = mapear([{ nome: 'Ana' }, { nome: 'Bob' }], u => u.nome);\n// nomes: string[]\n```\n\n## Generics em interfaces:\n```ts\ninterface ApiResponse<T> {\n  data: T;\n  status: number;\n  message: string;\n}\ntype UserResponse = ApiResponse<User>;\n```",
                        'task' => 'Crie uma função genérica "primeiro<T>(arr: T[]): T" que retorna o primeiro elemento de um array.',
                        'starter_code' => "function primeiro<T>(arr: T[]): T {\n  // Retorne o primeiro elemento\n}\nconsole.log(primeiro([1, 2, 3])); // 1\nconsole.log(primeiro(['a', 'b'])); // 'a'",
                        'solution_code' => "function primeiro<T>(arr: T[]): T { return arr[0]; } console.log(primeiro([1,2,3])); console.log(primeiro(['a','b']));",
                        'tips' => '<T extends object> restringe o genérico a objetos. Útil para funções que acessam propriedades.',
                        'examples' => "async function fetchData<T>(url: string): Promise<T> {\n  const res = await fetch(url);\n  return res.json() as T;\n}",
                        'real_world_case' => 'useState do React é genérico: const [user, setUser] = useState<User | null>(null).',
                        'docs_link' => 'https://www.typescriptlang.org/docs/handbook/2/generics.html',
