                    [
                        'title' => 'Utility Types: Tipos Prontos',
                        'slug' => 'ts-utility-types',
                        'content' => "# Utility Types: Transformando Tipos Existentes\n\nTypeScript inclui tipos utilitários built-in para manipular tipos sem reescrever.\n\n## Os mais usados:\n\n### Partial\\<T\\> — todos opcionais:\n```ts\ninterface User { id: number; nome: string; email: string; }\n\ntype UpdateUser = Partial<User>;\n// { id?: number; nome?: string; email?: string }\n\nfunction atualizar(id: number, dados: Partial<User>) { ... }\natualizar(1, { nome: 'Ana' }); // válido! Não precisa passar tudo\n```\n\n### Required\\<T\\> — todos obrigatórios:\n```ts\ntype UserCompleto = Required<User>; // remove todos os ?\n```\n\n### Pick\\<T, K\\> — seleciona campos:\n```ts\ntype UserPreview = Pick<User, 'id' | 'nome'>;\n// { id: number; nome: string } — sem email\n```\n\n### Omit\\<T, K\\> — remove campos:\n```ts\ntype CreateUser = Omit<User, 'id'>; // sem id (gerado pelo banco)\ntype UserPublico = Omit<User, 'senha' | 'token'>;\n```\n\n### Readonly\\<T\\> — imutável:\n```ts\ntype Config = Readonly<{ apiUrl: string; timeout: number }>;\nconst config: Config = { apiUrl: '...', timeout: 5000 };\nconfig.apiUrl = 'outro'; // Erro: readonly!\n```\n\n### Record\\<K, V\\> — mapa de chave/valor:\n```ts\ntype Permissoes = Record<string, boolean>;\nconst perms: Permissoes = { admin: true, editor: false };\n```",
                        'task' => 'Use Partial<> para criar um tipo de atualização de User onde todos os campos são opcionais.',
                        'starter_code' => "interface User { id: number; nome: string; email: string; }\n// Crie UpdateUser usando Partial\ntype UpdateUser = never; // substitua never pelo tipo correto\nconst update: UpdateUser = { nome: 'Ana' }; // válido sem id e email\nconsole.log(update);",
                        'solution_code' => "interface User { id: number; nome: string; email: string; } type UpdateUser = Partial<User>; const update: UpdateUser = { nome: 'Ana' }; console.log(update);",
